def remember(s):
    seen = set()
    result = []
    for i, char in enumerate(s):
        if char in seen:
            continue
        if s.count(char) > 1:
            last_index = s.rfind(char)
            if last_index == i + 1:
                result.append(char)
        seen.add(char)
    return result
